-- This header is used by the dbupdate tool.
-- The TARGET property is used to indicate which database the script is
-- intended to be executed on. The value can be either 'Surveillance' or
-- 'SurveillanceLog' without the quotes.
-- =========================================================================
-- TARGET: Surveillance
-- =========================================================================

IF EXISTS(SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[install_viewlayout]') AND type in (N'P', N'PC'))
BEGIN
	DROP PROCEDURE [install_viewlayout]
END
GO

IF EXISTS(SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[remove_viewlayout]') AND type in (N'P', N'PC'))
BEGIN
	DROP PROCEDURE [remove_viewlayout]
END
GO

CREATE PROCEDURE [install_viewlayout]
	@layout_group_id [GuidType],
	@layout_id [GuidType],
	@layout_name [NameType],
	@layout_definition Xml,
	@current_time DATETIME
AS
BEGIN
	SET NOCOUNT ON

	-- Add ViewLayout
	IF NOT EXISTS(SELECT * FROM [VideoWallViewLayout] WHERE [pkid] = @layout_id)
	BEGIN
		INSERT [VideoWallViewLayout] ([pkid], [name], [description], [created_date], [last_modified], [definition_xml])
		VALUES (
			@layout_id,
			@layout_name,
			'',
			@current_time,
			@current_time,
			@layout_definition
		)
	END
	ELSE
	BEGIN
		UPDATE [VideoWallViewLayout] 
		SET [name] = @layout_name,
			[created_date] = @current_time,
			[last_modified] = @current_time,
			[definition_xml] = @layout_definition
		WHERE [pkid] = @layout_id
	END

	-- Add ServerGroup Membership
	DELETE FROM [ServerGroupMembership]
	WHERE [IDObject] = @layout_id
	
	INSERT [ServerGroupMembership] ([IDServerGroup], [IDObject], [ObjectType], [LastModified])
	VALUES(
			@layout_group_id,
			@layout_id,
			'VIEWLAYOUT',
			@current_time
		   )
END
GO

CREATE PROCEDURE [remove_viewlayout]
	@layout_group_id [GuidType],
	@layout_id [GuidType]
AS
BEGIN
	SET NOCOUNT ON

	-- Delete ServerGroup Membership
	DELETE FROM [ServerGroupMembership] WHERE [IDServerGroup] = @layout_group_id AND [IDObject] = @layout_id

	-- Delete ViewLayout
	DELETE FROM [VideoWallViewLayout] WHERE [pkid] = @layout_id
END
GO

